export const TELUGU_FONTS = POSTER_FONTS.filter((f) => f.script === 'te')
export const ENGLISH_FONTS = POSTER_FONTS.filter((f) => f.script === 'en')
export const fontById = (id) => POSTER_FONTS.find((f) => f.id === id) || null
